-- Private source and contextual search, after publication.sql + regulation.sql.
reset role;
set local role anon;
select pg_temp.pu_error('select public.get_achievement_context(pg_temp.pu_id(3))','42501');
select pg_temp.pu_error('select public.list_achievement_athletes(pg_temp.pu_id(3))','42501');
set local role service_role;
select pg_temp.pu_error('select public.get_achievement_context(pg_temp.pu_id(3))','42501');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.pu_id(99)::text,true);
select pg_temp.pu_error('select public.get_achievement_context(pg_temp.pu_id(3))','PT403');
select set_config('request.jwt.claim.sub',pg_temp.pu_id(98)::text,true);
select pg_temp.pu_error('select public.get_achievement_context(pg_temp.pu_id(9999))','PT404');
do $$declare s jsonb;begin
 s:=public.get_game_occurrence_state(pg_temp.pu_id(9));
 perform public.save_game_occurrence(jsonb_build_object('commandId',pg_temp.pu_id(20000),'disputeId',s->'disputeId','gameId',pg_temp.pu_id(9),'occurrenceId',pg_temp.pu_id(20001),'expectedVersion',0,'expectedGameVersion',s->'gameVersion','expectedPublicationVersion',s->'publicationVersion','expectedRegulationVersion',s->'regulationVersion','expectedContextFingerprint',s->'contextFingerprint','effect',jsonb_build_object('kind','postponed'),'reason','Motivo administrativo reservado da fixture','acknowledgeImpact',true));
end$$;
create temp table ac_before as select public.get_achievement_context(pg_temp.pu_id(3)) value;
select pg_temp.pu_assert((select jsonb_array_length(value->'eligibleAthletes')=11 and value#>'{regulation,history}'='[]'::jsonb and value#>'{regulation,hasMore}'='false'::jsonb from ac_before),'all historical athletes, no audit reasons or actor IDs in source');
select pg_temp.pu_assert(public.get_achievement_context(pg_temp.pu_id(3))=(select value from ac_before),'visits and clock do not change source');
select pg_temp.pu_assert(position('birthDate' in (select value::text from ac_before))=0 and position('federationRegistration' in (select value::text from ac_before))=0 and position('1990-01-01' in (select value::text from ac_before))=0,'private identity details do not leak into source');
select pg_temp.pu_assert(position('Motivo administrativo reservado' in (select value::text from ac_before))=0,'suggestion source does not repeat private administrative motives');
reset role;
create temp table ac_recent as select saved_at from public.championships where id=pg_temp.pu_id(1);
update public.roster_entries set ended_at=clock_timestamp(),version=version+1 where id=pg_temp.pu_id(101);
update private.athletes set sex='female' where person_id=pg_temp.pu_id(201);
set local role authenticated;
select pg_temp.pu_assert(public.get_achievement_context(pg_temp.pu_id(3))=(select value from ac_before),'ending a period does not remove historical eligibility or change unrelated facts');
reset role;
insert into public.persons(id,name) select pg_temp.pu_id(10000+n),'Homônimo' from generate_series(1,25) n;
insert into private.athletes(person_id,sex) select pg_temp.pu_id(10000+n),'male' from generate_series(1,25) n;
insert into public.roster_entries(id,registration_id,dispute_id,person_id,jersey) select pg_temp.pu_id(11000+n),pg_temp.pu_id(5),pg_temp.pu_id(3),pg_temp.pu_id(10000+n),null from generate_series(1,25) n;
insert into public.persons(id,name) values(pg_temp.pu_id(12000),'Homônimo'),(pg_temp.pu_id(12001),'Homônimo');
insert into private.athletes(person_id,sex) values(pg_temp.pu_id(12000),'male');
insert into public.coaches(person_id) values(pg_temp.pu_id(12001));
set local role authenticated;
select pg_temp.pu_assert(public.get_achievement_context(pg_temp.pu_id(3))->>'contextFingerprint'<>(select value->>'contextFingerprint' from ac_before),'new eligible identity changes fingerprint');
select pg_temp.pu_assert(jsonb_array_length(public.get_achievement_context(pg_temp.pu_id(3))->'eligibleAthletes')=36,'global outsider and coach without context are not eligible');
select pg_temp.pu_assert(jsonb_array_length(public.list_achievement_athletes(pg_temp.pu_id(3),'homonimo',0)->'items')=20 and public.list_achievement_athletes(pg_temp.pu_id(3),'homonimo',0)->'hasMore'='true','accent-insensitive contextual search has bounded first page');
select pg_temp.pu_assert(jsonb_array_length(public.list_achievement_athletes(pg_temp.pu_id(3),'homonimo',20)->'items')=5 and public.list_achievement_athletes(pg_temp.pu_id(3),'homonimo',20)->'hasMore'='false','remaining homonyms stay distinct, no outsider returned');
select pg_temp.pu_assert(public.list_achievement_athletes(pg_temp.pu_id(3),'Player 1')->'items'->0->'registrationIds' @> jsonb_build_array(pg_temp.pu_id(5)),'ended membership remains selectable with its context');
select pg_temp.pu_error('select public.list_achievement_athletes(pg_temp.pu_id(3),repeat(''x'',121),0)','PT400');
select pg_temp.pu_error('select public.list_achievement_athletes(pg_temp.pu_id(3),'''',-1)','PT400');
select pg_temp.pu_error('select public.list_achievement_athletes(pg_temp.pu_id(3),'''',100001)','PT400');
create temp table ac_changed as select public.get_achievement_context(pg_temp.pu_id(3)) value;
reset role;
update public.persons set name='Nome corrigido',version=version+1 where id=pg_temp.pu_id(201);
set local role authenticated;
select pg_temp.pu_assert(public.get_achievement_context(pg_temp.pu_id(3))->>'contextFingerprint'<>(select value->>'contextFingerprint' from ac_changed),'public identity edit invalidates context without changing publication');
select public.get_achievement_context(pg_temp.pu_id(3)) as achievement_context;
select public.list_achievement_athletes(pg_temp.pu_id(3),'homonimo',20) as achievement_candidates;
reset role;
-- LOCAL_CAPACITY_BEGIN: real proof uses the smaller identity fixture above.
savepoint ac_capacity;
insert into public.persons(id,name) select pg_temp.pu_id(50000+n),'Capacidade '||n from generate_series(1,9964) n;
insert into private.athletes(person_id,sex) select pg_temp.pu_id(50000+n),'male' from generate_series(1,9964) n;
insert into public.roster_entries(id,registration_id,dispute_id,person_id,jersey) select pg_temp.pu_id(70000+n),pg_temp.pu_id(5),pg_temp.pu_id(3),pg_temp.pu_id(50000+n),null from generate_series(1,9964) n;
set local role authenticated;
select pg_temp.pu_assert(jsonb_array_length(public.get_achievement_context(pg_temp.pu_id(3))->'eligibleAthletes')=10000,'complete source at the boundary is not silently truncated');
reset role;
insert into public.persons(id,name) values(pg_temp.pu_id(60000),'Mais um atleta');
insert into private.athletes(person_id,sex) values(pg_temp.pu_id(60000),'male');
insert into public.roster_entries(id,registration_id,dispute_id,person_id,jersey) values(pg_temp.pu_id(80000),pg_temp.pu_id(5),pg_temp.pu_id(3),pg_temp.pu_id(60000),null);
set local role authenticated;
select pg_temp.pu_error('select public.get_achievement_context(pg_temp.pu_id(3))','PT413');
select pg_temp.pu_error('select public.list_achievement_athletes(pg_temp.pu_id(3))','PT413');
rollback to savepoint ac_capacity;
reset role;
-- LOCAL_CAPACITY_END
select pg_temp.pu_assert((select c.saved_at=r.saved_at from public.championships c cross join ac_recent r where c.id=pg_temp.pu_id(1)),'reads and search do not change Recentes');
select pg_temp.pu_assert(not has_function_privilege('anon','public.get_achievement_context(uuid)','EXECUTE') and not has_function_privilege('service_role','public.list_achievement_athletes(uuid,text,integer)','EXECUTE'),'no generic role grants');
update public.admin_access set enabled=false;
set local role authenticated;
select pg_temp.pu_error('select public.get_achievement_context(pg_temp.pu_id(3))','PT403');
select pg_temp.pu_error('select public.list_achievement_athletes(pg_temp.pu_id(3))','PT403');
reset role;
